_CYC = [2, 0, 3, 1, 3, 1, 0, 2]


def Q(prompt, options, right, whys, steps, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """4-option multiple choice. `right` = index of the correct option as written; `whys` = reasons for the wrong options in order.
    The correct option is then moved to a rotating target position so answers spread across A-D."""
    w = list(whys)
    if len(w) == 4:
        del w[right]
    items = [(t, i == right, "" if i == right else w.pop(0)) for i, t in enumerate(options)]
    good = [x for x in items if x[1]][0]
    rest = [x for x in items if not x[1]]
    pos = _CYC[_n[0] % 8]
    _n[0] += 1
    rest.insert(pos, good)
    return MC(prompt, [C(t, correct=c, why=y) for t, c, y in rest],
              steps=[S(f"Step {n}", text=t) if len(steps) > 1 else S("Answer", text=t) for n, t in enumerate(steps, 1)],
              concept=concept, skill=skill, hint=hint, feedback=feedback, diagram=diagram, diagram_alt=diagram_alt)


